package env

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

// EnvVar represents a single environment variable
type EnvVar struct {
	Key     string
	Value   string
	Managed bool // true if managed by lanup
}

// EnvWriter handles reading and writing environment files
type EnvWriter struct {
	FilePath      string
	BackupEnabled bool
}

// NewEnvWriter creates a new EnvWriter instance
func NewEnvWriter(path string) *EnvWriter {
	return &EnvWriter{
		FilePath:      path,
		BackupEnabled: true,
	}
}

// isEnvRC returns true if the output file uses shell export syntax (.envrc)
func (w *EnvWriter) isEnvRC() bool {
	base := filepath.Base(w.FilePath)
	return base == ".envrc" || strings.HasSuffix(base, ".envrc")
}

// Read parses an existing .env or .envrc file and returns the variables
func (w *EnvWriter) Read() ([]EnvVar, error) {
	file, err := os.Open(w.FilePath)
	if err != nil {
		if os.IsNotExist(err) {
			// File doesn't exist yet, return empty slice
			return []EnvVar{}, nil
		}
		return nil, fmt.Errorf("failed to open file %s: %w", w.FilePath, err)
	}
	defer file.Close()

	var vars []EnvVar
	scanner := bufio.NewScanner(file)
	managed := false

	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())

		// Check for lanup:managed marker
		if strings.Contains(line, "# lanup:managed") {
			managed = true
			continue
		}

		// Skip empty lines and comments (except managed marker)
		if line == "" || strings.HasPrefix(line, "#") {
			managed = false
			continue
		}

		// Strip "export " prefix for .envrc files
		parseLine := line
		if strings.HasPrefix(parseLine, "export ") {
			parseLine = strings.TrimPrefix(parseLine, "export ")
		}

		// Parse KEY=VALUE
		parts := strings.SplitN(parseLine, "=", 2)
		if len(parts) != 2 {
			continue
		}

		key := strings.TrimSpace(parts[0])
		value := strings.TrimSpace(parts[1])

		// Remove quotes if present
		value = strings.Trim(value, "\"'")

		vars = append(vars, EnvVar{
			Key:     key,
			Value:   value,
			Managed: managed,
		})

		managed = false
	}

	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("error reading file %s: %w", w.FilePath, err)
	}

	return vars, nil
}

// Backup creates a backup of the existing file with .bak extension
func (w *EnvWriter) Backup() error {
	// Check if the file exists
	if _, err := os.Stat(w.FilePath); os.IsNotExist(err) {
		// No file to backup
		return nil
	}

	backupPath := w.FilePath + ".bak"

	// Read the original file
	data, err := os.ReadFile(w.FilePath)
	if err != nil {
		return fmt.Errorf("failed to read file for backup: %w", err)
	}

	// Write to backup file
	err = os.WriteFile(backupPath, data, 0644)
	if err != nil {
		return fmt.Errorf("failed to create backup file: %w", err)
	}

	return nil
}

// Merge combines new variables with existing ones, preserving non-managed variables
func (w *EnvWriter) Merge(newVars []EnvVar, existing []EnvVar) []EnvVar {
	// Create a map of existing non-managed variables
	preserved := make(map[string]EnvVar)
	for _, v := range existing {
		if !v.Managed {
			preserved[v.Key] = v
		}
	}

	// Create result slice with new managed variables
	result := make([]EnvVar, 0, len(newVars)+len(preserved))

	// Add all new managed variables
	for _, v := range newVars {
		result = append(result, v)
	}

	// Add preserved non-managed variables
	for _, v := range preserved {
		result = append(result, v)
	}

	return result
}

// formatVar formats a single variable line based on the output file type
func (w *EnvWriter) formatVar(key, value string) string {
	if w.isEnvRC() {
		return fmt.Sprintf("export %s=%s\n", key, value)
	}
	return fmt.Sprintf("%s=%s\n", key, value)
}

// Write writes the environment variables to the file with proper formatting
func (w *EnvWriter) Write(vars []EnvVar) error {
	// Create backup if enabled
	if w.BackupEnabled {
		if err := w.Backup(); err != nil {
			return fmt.Errorf("failed to create backup: %w", err)
		}
	}

	// Ensure directory exists
	dir := filepath.Dir(w.FilePath)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return fmt.Errorf("failed to create directory: %w", err)
	}

	// Open file for writing
	file, err := os.Create(w.FilePath)
	if err != nil {
		return fmt.Errorf("failed to create file: %w", err)
	}
	defer file.Close()

	writer := bufio.NewWriter(file)

	// Write header
	timestamp := time.Now().Format("2006-01-02 15:04:05")
	header := fmt.Sprintf("# Generated by lanup on %s\n# Do not edit the managed variables manually\n\n", timestamp)
	if _, err := writer.WriteString(header); err != nil {
		return fmt.Errorf("failed to write header: %w", err)
	}

	// Separate managed and non-managed variables
	var managedVars []EnvVar
	var userVars []EnvVar

	for _, v := range vars {
		if v.Managed {
			managedVars = append(managedVars, v)
		} else {
			userVars = append(userVars, v)
		}
	}

	// Write managed variables
	for _, v := range managedVars {
		if _, err := writer.WriteString("# lanup:managed\n"); err != nil {
			return fmt.Errorf("failed to write managed marker: %w", err)
		}
		if _, err := writer.WriteString(w.formatVar(v.Key, v.Value)); err != nil {
			return fmt.Errorf("failed to write variable: %w", err)
		}
	}

	// Write separator if there are user variables
	if len(userVars) > 0 {
		if _, err := writer.WriteString("\n# User variables (preserved)\n"); err != nil {
			return fmt.Errorf("failed to write separator: %w", err)
		}

		// Write user variables
		for _, v := range userVars {
			if _, err := writer.WriteString(w.formatVar(v.Key, v.Value)); err != nil {
				return fmt.Errorf("failed to write variable: %w", err)
			}
		}
	}

	// Flush the buffer
	if err := writer.Flush(); err != nil {
		return fmt.Errorf("failed to flush writer: %w", err)
	}

	return nil
}

// assignment is a parsed KEY=VALUE line, with how it was written
type assignment struct {
	key    string
	export bool
	quote  string // "", `"` or `'`
}

// parseAssignment reads a KEY=VALUE or export KEY=VALUE line; comments and
// shell commands are not assignments
func parseAssignment(line string) (assignment, bool) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" || strings.HasPrefix(trimmed, "#") {
		return assignment{}, false
	}
	a := assignment{}
	if strings.HasPrefix(trimmed, "export ") {
		a.export = true
		trimmed = strings.TrimSpace(strings.TrimPrefix(trimmed, "export "))
	}
	parts := strings.SplitN(trimmed, "=", 2)
	if len(parts) != 2 || !isIdentifier(parts[0]) {
		return assignment{}, false
	}
	a.key = parts[0]
	if v := parts[1]; strings.HasPrefix(v, `"`) || strings.HasPrefix(v, `'`) {
		a.quote = v[:1]
	}
	return a, true
}

func isIdentifier(s string) bool {
	if s == "" {
		return false
	}
	for i, r := range s {
		letter := r == '_' || (r >= 'A' && r <= 'Z') || (r >= 'a' && r <= 'z')
		if !letter && (i == 0 || r < '0' || r > '9') {
			return false
		}
	}
	return true
}

// shellUnsafe lists the characters that need quoting in a shell assignment
const shellUnsafe = " \t\"'`$\\<>|&;()*?[]#~{}!"

// formatAssignment writes a variable the way its line was written before
// (export prefix, quotes); a shell file quotes values that need it
func formatAssignment(a assignment, value string, shell bool) string {
	quote := a.quote
	if quote == "" && shell && strings.ContainsAny(value, shellUnsafe) {
		quote = `"`
	}
	if quote == `'` && strings.Contains(value, "'") {
		quote = `"`
	}
	if quote == `"` {
		value = strings.NewReplacer(`\`, `\\`, `"`, `\"`, "$", `\$`, "`", "\\`").Replace(value)
	}
	prefix := ""
	if a.export || shell {
		prefix = "export "
	}
	return prefix + a.key + "=" + quote + value + quote
}

// Update writes the managed variables in place: their lines are rewritten,
// keeping their export prefix and quotes, and every other line (comments,
// unmanaged variables, shell commands) stays as it is. Variables not yet in the
// file are appended under a lanup:managed marker. No line is ever removed: a
// variable no longer in the config keeps its last value.
func (w *EnvWriter) Update(vars []EnvVar) error {
	data, err := os.ReadFile(w.FilePath)
	if err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to read file %s: %w", w.FilePath, err)
	}
	mode := os.FileMode(0644)
	if info, statErr := os.Stat(w.FilePath); statErr == nil {
		mode = info.Mode().Perm()
	}

	want := make(map[string]string, len(vars))
	for _, v := range vars {
		want[v.Key] = v.Value
	}
	shell := w.isEnvRC()

	var lines []string
	if content := strings.TrimRight(string(data), "\n"); content != "" {
		lines = strings.Split(content, "\n")
	}

	written := make(map[string]bool, len(vars))
	out := make([]string, 0, len(lines)+2*len(vars))
	for _, line := range lines {
		a, ok := parseAssignment(line)
		if ok {
			if value, managed := want[a.key]; managed {
				out = append(out, formatAssignment(a, value, shell))
				written[a.key] = true
				continue
			}
		}
		out = append(out, line)
	}

	var missing []string
	for key := range want {
		if !written[key] {
			missing = append(missing, key)
		}
	}
	sort.Strings(missing)
	if len(missing) > 0 && len(out) > 0 && strings.TrimSpace(out[len(out)-1]) != "" {
		out = append(out, "")
	}
	for _, key := range missing {
		out = append(out, "# lanup:managed", formatAssignment(assignment{key: key}, want[key], shell))
	}

	content := strings.Join(out, "\n") + "\n"
	if content == string(data) {
		return nil
	}
	if w.BackupEnabled {
		if err := w.Backup(); err != nil {
			return fmt.Errorf("failed to create backup: %w", err)
		}
	}
	if err := os.MkdirAll(filepath.Dir(w.FilePath), 0755); err != nil {
		return fmt.Errorf("failed to create directory: %w", err)
	}
	if err := os.WriteFile(w.FilePath, []byte(content), mode); err != nil {
		return fmt.Errorf("failed to write file %s: %w", w.FilePath, err)
	}
	return nil
}
